{
  "core_question": "How should a self‑insured employer evaluate and implement coverage of GLP‑1 medications for obesity in terms of clinical appropriateness, legal compliance, and financial impact?",
  "rationale": "The decision involves medical evidence and utilization criteria (healthcare), statutory and regulatory obligations for self‑insured plans (legal), and cost/benefit analysis including drug pricing and potential savings (finance).",
  "routes": ["healthcare", "legal", "finance"],
  "sub_questions": {
    "healthcare": "For a 5,000‑employee self‑insured employer considering coverage of GLP‑1 medications such as semaglutide and tirzepatide for obesity, what clinical criteria (e.g., BMI thresholds, prior weight loss attempts, comorbidities) should be used to select patients, what monitoring protocols are recommended, and how do current efficacy and safety data support these utilization‑management rules?",
    "legal": "What ERISA, ACA, and state‑level legal requirements must a self‑insured employer meet when adding GLP‑1 obesity coverage, including anti‑discrimination obligations, privacy considerations, and potential liability for adverse events or off‑label use?",
    "finance": "Assuming average drug costs and utilization rates for semaglutide and tirzepatide, what is the projected annual budget impact for a 5,000‑employee self‑insured plan, how might rebates or value‑based contracts alter this figure, and what potential cost savings could arise from reduced obesity‑related health claims?"
  },
  "requires_recency_disclosure": true,
  "recency_notes": "Drug pricing, rebate structures, and FDA labeling for tirzepatide/semaglutide may have changed after 2024; recent payer contracts and utilization guidelines are also time‑sensitive."
}
